// Attachment represents a file attached to an agent execution.
//
//	All files must be pre-uploaded via the uploadAttachment RPC and referenced
//	by storage_key. This ensures consistent behavior regardless of file size.
//
//	## Usage Flow
//
//	1. Client calls uploadAttachment RPC with file content
//	2. Server returns a storage_key
//	3. Client creates execution with Attachment containing that storage_key
//	4. Agent-runner downloads file from storage and injects into sandbox
//
//	## Mount Path
//
//	The mount_path determines where the file appears in the sandbox.
//	If not specified, defaults to /inputs/{filename}
//
//	Examples:
//	  - mount_path: "/inputs/config.yaml" -> file at /inputs/config.yaml
//	  - mount_path: "/workspace/data/" -> directory extracted at /workspace/data/
//
//	@since Artifact Lifecycle (Attachments & Outputs)
type Attachment struct {
	// Original filename for display and default mount path derivation.  Example: "config.yaml", "input-data.zip"
	Filename string `json:"filename,omitempty"`
	// Reference to pre-uploaded file in artifact store (required).  Obtained by calling uploadAttachment RPC before creating the execution.  Format: "attachments/{ulid}/{filename}"
	StorageKey string `json:"storageKey,omitempty"`
	// Path in sandbox where file will be placed.  Defaults to "/inputs/{filename}" if not specified.  Example: "/workspace/input.yaml", "/inputs/data/"
	MountPath string `json:"mountPath,omitempty"`
	// MIME type for content negotiation (optional).  Example: "application/yaml", "text/plain", "application/zip"
	ContentType string `json:"contentType,omitempty"`
	// When true, the attachment is a zip archive that should be extracted  at mount_path rather than written as a single file.  Set automatically by the CLI when a directory is attached.
	Extract bool `json:"extract,omitempty"`
	// Absolute filesystem path to the original file on the CLI host (optional).   When set and the runner is in local mode, the file is read directly  from this path instead of downloading from artifact storage via  storage_key.  This eliminates the storage round-trip for local  executions.   Ignored when the runner is not in local mode (cloud runners use  storage_key exclusively).   The CLI sets this unconditionally to the resolved absolute path of  the attached file.  storage_key remains required -- the upload still  happens for execution history and replay support.
	LocalPath string `json:"localPath,omitempty"`
}

// FromProto converts google.protobuf.Struct to Attachment.
func (c *Attachment) FromProto(s *structpb.Struct) error {
	fields := s.GetFields()

	if val, ok := fields["filename"]; ok {
		c.Filename = val.GetStringValue()
	}

	if val, ok := fields["storageKey"]; ok {
		c.StorageKey = val.GetStringValue()
	}

	if val, ok := fields["mountPath"]; ok {
		c.MountPath = val.GetStringValue()
	}

	if val, ok := fields["contentType"]; ok {
		c.ContentType = val.GetStringValue()
	}

	if val, ok := fields["extract"]; ok {
		c.Extract = val.GetBoolValue()
	}

	if val, ok := fields["localPath"]; ok {
		c.LocalPath = val.GetStringValue()
	}

	return nil
}

// Configuration that can be applied at execution time.
type ExecutionConfig struct {
	// The model to use for this execution.  Example: "claude-sonnet-4-6"
	ModelName string `json:"modelName,omitempty"`
	// Context management configuration for this execution.  Controls automatic summarization behavior for long-running conversations.  When not specified, defaults are derived from the Model Registry.
	ContextManagement *ContextManagementConfig `json:"contextManagement,omitempty"`
	// Maximum number of model-to-tools reasoning cycles per message.   Each "round" is one model call followed by tool execution — the atomic  unit of agent progress.  Internally mapped to LangGraph's recursion_limit  (approximately max_tool_rounds × 6 super-steps).   ## Conversion   LangGraph's recursion_limit counts "super-steps" — individual graph node  executions.  Each model-tool round consumes multiple super-steps because  every active middleware hook (before_model, after_model, etc.) is a  separate graph node.  The conversion formula is:     recursion_limit = max_tool_rounds × 6   The ×6 factor is a floor estimate; actual cost per round depends on the  middleware stack.   ## Default Behavior   0 = unlimited (no artificial recursion limit).  The agent runs until the task completes or loop detection middleware  detects repetitive behavior (7 consecutive / 20 total duplicate  patterns).  This is the recommended default — loop detection is the  primary safety mechanism.   ## Valid Range   When set: 10–1000 rounds (60–6000 super-steps).  Values outside this range are clamped to the nearest bound with a  warning log.  Sub-agent graphs have their own independent recursion  limit (LangGraph default: 10,000) and are not affected by this field.   ## User Experience   When a limit IS set and the agent approaches it, a graceful wrap-up  message is injected at ~80% of the budget.  At 100%, the user sees  a "send another message to continue" prompt.   @since Recursion Limit Configurability (D1)
	MaxToolRounds int32 `json:"maxToolRounds,omitempty"`
	// Maximum number of characters for a single tool result before truncation.  When a tool result exceeds this limit, it is truncated and a marker is  appended: "[truncated — result exceeded {limit} chars, ask for specific sections]"   0 = use platform default (recommended: 30,000 chars ~ 7,500 tokens).  Set higher for agents that work with large files/outputs.   Applies to all tool results (shell, read, write, MCP tools).  Does not apply to built-in tools that already manage their output size.
	MaxToolResultChars int32 `json:"maxToolResultChars,omitempty"`
	// Maximum estimated cost in USD for this execution.  When the running cost exceeds this limit, the agent receives a  "budget exhausted" message and the execution transitions to TERMINATED.   0.0 = no cost cap (default, unlimited).  Recommended: 1.00-5.00 for interactive sessions, 10.00+ for batch workflows.   Cost is checked after each LLM call using the running total from  UsageMetrics.estimated_cost_usd. When approaching the cap (>80%),  a budget warning is injected into the conversation.
	MaxCostUsd float64 `json:"maxCostUsd,omitempty"`
}

// FromProto converts google.protobuf.Struct to ExecutionConfig.
func (c *ExecutionConfig) FromProto(s *structpb.Struct) error {
	fields := s.GetFields()

	if val, ok := fields["modelName"]; ok {
		c.ModelName = val.GetStringValue()
	}

	if val, ok := fields["contextManagement"]; ok {
		c.ContextManagement = &ContextManagementConfig{}
		if err := c.ContextManagement.FromProto(val.GetStructValue()); err != nil {
			return err
		}
	}

	if val, ok := fields["maxToolRounds"]; ok {
		c.MaxToolRounds = int32(val.GetNumberValue())
	}

	if val, ok := fields["maxToolResultChars"]; ok {
		c.MaxToolResultChars = int32(val.GetNumberValue())
	}

	if val, ok := fields["maxCostUsd"]; ok {
		c.MaxCostUsd = val.GetNumberValue()
	}

	return nil
}

