// HttpServerConfig defines an MCP server accessible via HTTP + Server-Sent Events.
//
//	@internal
//	Communication flow:
//	1. Agent sends JSON-RPC requests via HTTP POST
//	2. Server streams responses via Server-Sent Events (SSE)
//
//	Use cases:
//	- Managed MCP services (e.g., hosted by a cloud provider)
//	- MCP servers behind a reverse proxy or API gateway
//	- Sharing a single MCP server instance across multiple agents
type HttpServerConfig struct {
	// Base URL of the MCP server endpoint.  Must be a valid HTTP or HTTPS URL.  Examples:  - "http://localhost:3000/mcp"  - "https://mcp.example.com/v1"  - "https://api.company.com/mcp/github"
	Url string `json:"url,omitempty"`
	// HTTP headers to include with every request.  Use for authentication, API versioning, or custom routing.   Header values can reference environment variables using ${VAR_NAME} syntax.  These placeholders are resolved at runtime from AgentInstance's environment.   Examples:    "Authorization": "Bearer ${API_TOKEN}"    "X-API-Version": "2024-01"    "X-Tenant-ID": "${TENANT_ID}"
	Headers map[string]string `json:"headers,omitempty"`
	// Query parameters to append to the URL.  Values can reference environment variables using ${VAR_NAME} syntax.   Examples:    "region": "${AWS_REGION}"    "version": "v1"
	QueryParams map[string]string `json:"queryParams,omitempty"`
	// Timeout for HTTP requests in seconds.  Applies to both the initial connection and response streaming.  Default: 30 seconds if not specified.  Set higher values for MCP servers that perform long-running operations.
	TimeoutSeconds int32 `json:"timeoutSeconds,omitempty"`
}

